      <TextInput
        name="title"
        size="l"
        label="Название"
        value={title}
        onUpdate={setTitle}
      />

      <MarkdownField
        name="text"
        label="Текст (Markdown)"
        value={text}
        onChange={setText}
        placeholder="Пишите в Markdown…"
      />

      <div>
        <Button type="submit" view="action" size="l">
          Сохранить
        </Button>
      </div>

      {submitted && (
        <Text color="secondary">
          Отправлено: «{submitted.title || 'без названия'}», {submitted.text.length} символов
        </Text>
      )}
    </form>
  );
}
